#!/usr/bin/env python3
"""Fetch every order page and every referenced customer from the order service.

Usage: python3 -I fetch.py OUT_DIR [--customers-from PAGES_DIR]

Writes:
  OUT_DIR/pages/page_NNN.json      raw body of the one accepted response per page
  OUT_DIR/customers/<id>.json      raw body of the accepted response per customer
  OUT_DIR/customers_404.json       customer ids that consistently returned 404
  OUT_DIR/requests.jsonl           every HTTP exchange, including failures
"""
import email.utils
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 80
RETRY_MARGIN = 0.05          # seconds added on top of the server's Retry-After
NOT_FOUND_CONFIRMATIONS = 4  # a 404 must repeat this many times before we accept it


def lower_headers(headers):
    return {k.lower(): v for k, v in headers.items()}


def retry_after_seconds(headers, body):
    """Largest wait the server asked for, from the header and/or the JSON body."""
    waits = []
    value = lower_headers(headers).get("retry-after")
    if value is not None:
        try:
            waits.append(float(value))
        except ValueError:
            try:
                waits.append(email.utils.parsedate_to_datetime(value).timestamp() - time.time())
            except (TypeError, ValueError):
                pass
    try:
        parsed = json.loads(body)
        if isinstance(parsed, dict) and "retry_after" in parsed:
            waits.append(float(parsed["retry_after"]))
    except (ValueError, TypeError):
        pass
    return max(waits) if waits else None


class Client:
    def __init__(self, log_path):
        self.token = None
        self.stats = {}
        self.log = open(log_path, "a", encoding="utf-8")

    def bump(self, key):
        self.stats[key] = self.stats.get(key, 0) + 1

    def record(self, **fields):
        fields["ts"] = time.time()
        self.log.write(json.dumps(fields) + "\n")
        self.log.flush()

    def send(self, method, path, auth):
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, method=method, data=data)
        if auth:
            req.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as err:
            try:
                body = err.read()
            except Exception as read_err:  # noqa: BLE001 - keep going, the status is what matters
                body = repr(read_err).encode()
            return err.code, dict(err.headers or {}), body
        except (urllib.error.URLError, http.client.HTTPException, OSError) as err:
            return None, {}, repr(err).encode()

    def backoff(self, attempt):
        time.sleep(min(0.25 * 2 ** min(attempt, 6), 8.0))

    def wait_rate_limit(self, headers, body):
        wait = retry_after_seconds(headers, body)
        if wait is None:
            self.bump("429_without_retry_after")
            wait = 1.0
        time.sleep(max(wait, 0) + RETRY_MARGIN)

    def refresh_token(self):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, headers, body = self.send("POST", "/token", auth=False)
            self.record(method="POST", path="/token", status=status, headers=headers,
                        body=body.decode("utf-8", "replace")[:500], attempt=attempt)
            self.bump(f"token_status_{status}")
            if status == 200:
                try:
                    token = json.loads(body).get("token")
                except (ValueError, AttributeError):
                    token = None
                if isinstance(token, str) and token:
                    self.token = token
                    self.bump("token_issued")
                    return
            if status == 429:
                self.wait_rate_limit(headers, body)
            else:
                self.backoff(attempt)
        raise RuntimeError("could not obtain a token")

    def get(self, path, validate, accept_404=False):
        """Return (status, raw_body, parsed) for a valid 200, or a 404 when accept_404."""
        if self.token is None:
            self.refresh_token()
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, headers, body = self.send("GET", path, auth=True)
            text = body.decode("utf-8", "replace")
            self.record(method="GET", path=path, status=status, headers=headers,
                        body=text if status != 200 else text[:200],
                        token=self.token, attempt=attempt)
            self.bump(f"get_status_{status}")
            if status == 200:
                try:
                    parsed = json.loads(body)
                    problem = validate(parsed)
                except ValueError as err:
                    parsed, problem = None, f"invalid json: {err}"
                if problem is None:
                    return 200, body, parsed
                self.bump("invalid_200")
                self.record(event="invalid_200", path=path, problem=problem, body=text)
                self.backoff(attempt)
            elif status in (401, 403):
                self.refresh_token()
            elif status == 429:
                self.wait_rate_limit(headers, body)
            elif status == 404 and accept_404:
                return 404, body, None
            else:
                self.backoff(attempt)
        raise RuntimeError(f"giving up on {path}")


def page_validator(expected_page):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        for key in ("page", "total_pages", "items", "next"):
            if key not in d:
                return f"missing key {key}"
        if d["page"] != expected_page:
            return f"page field {d['page']!r} != requested {expected_page}"
        if not isinstance(d["items"], list):
            return "items is not a list"
        if not isinstance(d["total_pages"], int):
            return "total_pages is not an int"
        return None
    return validate


def customer_validator(expected_id):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        for key in ("id", "name", "region", "tier", "discount_pct"):
            if key not in d:
                return f"missing key {key}"
        if d["id"] != expected_id:
            return f"id {d['id']!r} != requested {expected_id!r}"
        return None
    return validate


def page_number(path):
    query = urllib.parse.parse_qs(urllib.parse.urlparse(path).query)
    return int(query["page"][0])


def fetch_pages(client, out_dir):
    pages_dir = os.path.join(out_dir, "pages")
    os.makedirs(pages_dir, exist_ok=True)
    fetched = {}          # page number -> parsed body
    next_links = {}       # page number -> "next" value as served
    pending = ["/orders?page=1"]
    while pending:
        path = pending.pop(0)
        n = page_number(path)
        if n in fetched:
            continue
        _, raw, parsed = client.get(path, page_validator(n))
        with open(os.path.join(pages_dir, f"page_{n:03d}.json"), "wb") as fh:
            fh.write(raw)
        fetched[n] = parsed
        next_links[n] = parsed["next"]
        if parsed["next"] is not None:
            pending.append(parsed["next"])
        print(f"page {n}: {len(parsed['items'])} items, total_pages={parsed['total_pages']}, "
              f"next={parsed['next']!r}", flush=True)
    # Independently of the next chain, make sure every advertised page was fetched.
    advertised = max(p["total_pages"] for p in fetched.values())
    for n in range(1, advertised + 1):
        if n not in fetched:
            print(f"page {n} not reached via next links; fetching directly", flush=True)
            _, raw, parsed = client.get(f"/orders?page={n}", page_validator(n))
            with open(os.path.join(pages_dir, f"page_{n:03d}.json"), "wb") as fh:
                fh.write(raw)
            fetched[n] = parsed
            next_links[n] = parsed["next"]
    return fetched, next_links


def fetch_customers(client, out_dir, customer_ids):
    cust_dir = os.path.join(out_dir, "customers")
    os.makedirs(cust_dir, exist_ok=True)
    not_found = []
    for cid in sorted(customer_ids):
        target = os.path.join(cust_dir, urllib.parse.quote(cid, safe="") + ".json")
        if os.path.exists(target):
            continue  # cached from an earlier run
        path = "/customers/" + urllib.parse.quote(cid, safe="")
        misses = 0
        while True:
            status, raw, _ = client.get(path, customer_validator(cid), accept_404=True)
            if status == 200:
                with open(target, "wb") as fh:
                    fh.write(raw)
                break
            misses += 1
            if misses >= NOT_FOUND_CONFIRMATIONS:
                not_found.append(cid)
                break
            time.sleep(0.5)
    with open(os.path.join(out_dir, "customers_404.json"), "w") as fh:
        json.dump(not_found, fh)
    return not_found


def main():
    out_dir = sys.argv[1]
    os.makedirs(out_dir, exist_ok=True)
    client = Client(os.path.join(out_dir, "requests.jsonl"))
    started = time.time()
    fetched, next_links = fetch_pages(client, out_dir)
    customer_ids = {item["customer_id"] for page in fetched.values() for item in page["items"]
                    if isinstance(item, dict) and "customer_id" in item}
    print(f"{len(fetched)} pages, {len(customer_ids)} distinct customer ids", flush=True)
    not_found = fetch_customers(client, out_dir, customer_ids)
    print(f"customers not found: {not_found}", flush=True)
    print(f"stats: {json.dumps(client.stats, sort_keys=True)}", flush=True)
    print(f"elapsed {time.time() - started:.1f}s", flush=True)


if __name__ == "__main__":
    main()

